"""Checks the numbers of Sections 8-10 and of Tables 1 and 2 of the paper against the logs.

Run from the repository root, after code/run_scans.sh, code/run_models.sh and code/run_misc.sh:
    python3 code/check_small.py
Every check is an assertion; the script ends with ALL CHECKS PASSED.
"""
import csv
import re
from math import gcd
from pathlib import Path


def subgroup(n, gens):
    """The subgroup of (Z/nZ)^x generated by -1 and gens, as a frozenset of residues."""
    seen, todo = {1}, [1]
    while todo:
        a = todo.pop()
        for b in [-1] + list(gens):
            c = a * b % n
            if c not in seen:
                seen.add(c)
                todo.append(c)
    return frozenset(seen)


def ints(s):
    return [int(x) for x in re.findall(r"-?\d+", s)]


def read_tsv(path):
    lines = [l for l in Path(path).read_text().splitlines() if not l.startswith("#")]
    return list(csv.DictReader(lines, delimiter="\t"))


# --- Section 8: the scans of the levels 13 <= N <= 200 -----------------------------------------------------------
scan = {}
for n in range(13, 201):
    text = Path(f"logs/xdelta/N{n}.log").read_text()
    assert "DONE" in text and f"SUMMARY N={n} " in text, n
    for ns, gs, idx, genus, rest, status in re.findall(
            r"DELTA N=(\d+) gens=\[([^\]]*)\] idx=(\d+) genus=(\d+)([^\n]*) (OK|FAIL)\n", text):
        key = n, subgroup(n, ints(gs))
        assert int(ns) == n and key not in scan
        scan[key] = int(idx), int(genus), status, rest
assert len(scan) == 1449
fails = {k for k, v in scan.items() if v[2] == "FAIL"}
assert len(scan) - len(fails) == 1362 and len(fails) == 87
x0 = sorted(n for (n, d) in fails if scan[(n, d)][0] == 1)
x1 = sorted(n for (n, d) in fails if d == subgroup(n, []))
assert x0 == [22, 23, 26, 28, 29, 30, 31, 33, 34, 35, 37, 38, 39, 40, 42, 43, 44, 45, 48,
              50, 54, 56, 57, 60, 61, 63, 64, 72, 80, 81, 84, 96, 98, 100, 108, 128, 144]
assert x1 == [13, 16, 18, 20, 21, 22, 24, 30]
print("Scans of 13 <= N <= 200: 1449 curves of genus >= 2, 1362 satisfy a condition, 87 do not:",
      "37 curves X_0(N), 8 curves X_1(N) and 42 others.")
# The failing curves of levels 37, 63 and 108 are those of the main theorem.
exceptional = {(37, subgroup(37, [2])), (37, subgroup(37, [8])), (63, subgroup(63, [2, 5])),
               (63, subgroup(63, [59, 37])), (108, subgroup(108, [5]))}
assert {(n, d) for (n, d) in fails if n in (37, 63, 108)} == exceptional
print("The curves of levels 37, 63 and 108 that fail are X_0(37), X_0(63), X_0(108), X_{<8>}(37) and X_{<59,37>}(63).")

# --- Table 1 --------------------------------------------------------------------------------------------------
table = read_tsv("code/table_small.tsv")
rows = {}
for r in table:
    n = int(r["N"])
    key = n, subgroup(n, ints(r["gens"]))
    assert key in fails and scan[key][:2] == (int(r["i"]), int(r["g"])), key
    rows[key] = r
assert set(rows) == {k for k in fails if scan[k][0] > 1 and len(k[1]) > 2} and len(rows) == 42
print("Table 1: the 42 rows are exactly the other failing curves, with the same i_Delta and g_Delta.")

# #Aut over finite fields (canon2.m), and the two explicitly computed curves.
aut = {}
for p in sorted(Path("logs/canon2").glob("*.log")):
    m = re.search(r"RESULT N=(\d+) Delta=\[([^\]]*)\] g=(\d+) ell=(\d+) k=(\d+) : \|Aut\(X_Fbar\)\| = (\d+), "
                  r"\|B_Delta\| = (\d+)", p.read_text())
    assert m, p
    n = int(m[1])
    aut[(n, frozenset(ints(m[2])))] = int(m[6]), int(m[7])
t4 = Path("logs/models/t4.log").read_text()
assert "Geometric Aut X_{+-8}(21): order 12 " in t4
aut[(21, subgroup(21, [13, 8]))] = 12, None
x63 = Path("logs/models/review_xdelta63.log").read_text()
assert "|Aut X_Delta2(63)| = 96" in x63 and "diamond central in group of order 96" in x63
assert "ALL CHECKS PASSED" in x63
ff = Path("logs/models/review_frobenius_fields.log").read_text()
assert "X_0(63): full geometric special-fibre automorphism group has order 48." in ff and "ALL CHECKS PASSED" in ff
# Modular automorphisms from explicit matrices (normalizer.m, only the normalizer of Gamma_0(N)).
norm = {}
for line in Path("logs/normalizer.log").read_text().splitlines():
    m = re.match(r"NORMALIZER N=(\d+) Delta=\[([^\]]*)\] .*\|Norm/Gamma_Delta\|=(\d+) \|B_Delta\|=(\d+)", line)
    assert m, line
    norm[(int(m[1]), frozenset(ints(m[2])))] = int(m[3])
assert set(norm) == set(rows)
# Section 10: the index of the normalizer for N <= 200.
order = {}
for r in read_tsv("logs/aut_orders_13_200.tsv"):
    n = int(r["N"])
    key = n, subgroup(n, ints(r["gens"]))
    assert key not in order
    order[key] = r
assert set(order) == set(scan)

computed = descent = 0
for key, r in rows.items():
    n, d = key
    entry = r["entry"]
    m = re.match(r"(\d+)(?:/(\d+))?(?:, ([ab])\)(\*?))?$", entry)
    assert m, entry
    total, modular, cond, star = int(m[1]), int(m[2] or m[1]), m[3], m[4]
    assert int(order[key]["AutMod"]) == modular, (key, entry)
    if cond is None:
        computed += 1
        if key != (63, subgroup(63, [59, 37])):
            assert aut[key][0] == total, (key, aut[key], entry)
        if n in (49, 50):
            # The normalizer is not contained in that of Gamma_0(N) (Table 2); see the remark on X(7) and Bring's curve.
            assert norm[key] < modular
        else:
            assert norm[key] == modular, (key, norm[key], entry)
        continue
    descent += 1
    text = Path(f"logs/c4/N{n}_D{r['gens'].replace(',', '_')}.log").read_text()
    lines = re.findall(r"C4CHECK N=\d+ Delta=\S+ Delta'=\[([^\]]*)\] index=(\d+) g'=(\d+) cm'\(bound\)=\[([^\]]*)\] "
                       r"cm_complement=\[([^\]]*)\] overlapD=\[([^\]]*)\] coprime_any_p=(\d+)", text)
    big = subgroup(75, [4, 26]) if star else subgroup(n, [x for x in range(1, n) if gcd(x, n) == 1])
    ok = False
    for gs, index, g2, cma, cmb, overlap, anyp in lines:
        if subgroup(n, ints(gs)) != big:
            continue
        assert int(g2) >= 2 and int(anyp) > 0
        if cond == "a":
            ok = ints(overlap) == []
        else:
            dimS = sum(a + b for a, b in zip(ints(cma), ints(cmb)) if a > 0 and b > 0)
            ok = int(index) == 2 and 2 * dimS < int(r["g"]) - 1
            print(f"  N={n}: condition b) with dim S <= {dimS}, g_Delta = {r['g']}")
    assert ok, key
assert computed == 30 and descent == 12
# For N = 75 the curve X_{<4,26>}(75) satisfies a condition of the proposition on correspondences.
assert scan[(75, subgroup(75, [4, 26]))][2] == "OK"
print("Table 1: the 30 computed numbers agree with canon2.m, t4.m and review_xdelta63.m; the modular automorphisms",
      "agree with normalizer.m (except N = 49, 50) and with Section 10; the 12 descent rows satisfy a) or b).")

# X_1(N) for N in {13, 16, 18, 20, 21, 22, 24, 30}: all the automorphisms are modular.
t2 = Path("logs/models/t2.log").read_text()
assert "Geometric Aut X_1(13): order 12 " in t2 and int(order[(13, subgroup(13, []))]["AutMod"]) == 12
ts = Path("logs/models/t_small.log").read_text()
for n, a in [(16, 8), (18, 12), (20, 16)]:
    assert re.search(rf"X_1\({n}\)[^\n]*\|Aut_Qbar\| = {a} [^\n]*\|B\| = {a}\n", ts), n
    assert int(order[(n, subgroup(n, []))]["AutMod"]) == a
for n in (21, 22, 24, 30):
    a, b = aut[(n, subgroup(n, []))]
    assert a == b == int(order[(n, subgroup(n, []))]["AutMod"]), n
print("X_1(N), N in {13, 16, 18, 20, 21, 22, 24, 30}: #Aut equals the number of modular automorphisms.")

# --- Section 9 and the remark on Momose's preprint --------------------------------------------------------------
x063 = Path("logs/models/x063.log").read_text()
assert "|Aut X_0(63) over F_(127^2)| = 48" in x063 and "automorphisms preserving the set of cusps: 24 " in x063
t37c = Path("logs/models/t37c.log").read_text()
orders = re.findall(r"ell=(\d+) #X\(F_ell\)=\d+ : ord\(b2\)=(\d+) ", t37c)
assert [o for _, o in orders] == ["21"] * 5 and [int(l) for l, _ in orders] == [3, 5, 7, 11, 13]
print("Level 37: the class of (0_i) - (0_1) has order 21 modulo 3, 5, 7, 11 and 13.")
enum = Path("logs/models/enum.log").read_text()
first = [int(m[1]) for m in re.finditer(r"N=(\d+) [^\n]*NONSTABLE=\[ \d", enum)]
assert first and min(first) == 65
print("Square-free N <= 70: some w_Q does not normalize Gamma_Delta(N) first for N = 65.")

# --- Section 10 and Table 2 --------------------------------------------------------------------------------------
big_order = read_tsv("logs/aut_orders_201_400.tsv")
assert len(order) + len(big_order) == 4397
for path in ["logs/aut_orders_13_200.err", "logs/aut_orders_201_400.err"]:
    assert "normalizer inside M_Delta for all curves: True" in Path(path).read_text(), path
diff_h = [k for k, r in order.items() if r["h_Delta"] != r["h"]]
extra = {k for k, r in order.items() if r["AutMod"] != r["AutInNormG0"]}
assert len(diff_h) == 58 and len(extra) == 28 and extra <= set(diff_h)
t2rows = {}
for r in read_tsv("code/table_order.tsv"):
    n = int(r["N"])
    t2rows[(n, subgroup(n, ints(r["gens"])))] = r
assert set(t2rows) == extra
for k, r in t2rows.items():
    o = order[k]
    assert (o["i_Delta"], o["genus"], o["AutInNormG0"], o["AutMod"]) == (r["i"], r["g"], r["iDsD"], r["aut"]), k
print("Section 10: 4397 curves with N <= 400 (1449 with N <= 200), every normalizing matrix in M_Delta;",
      "58 curves with h_Delta != h(N), 28 of them in Table 2, which agrees with the computation.")
print("ALL CHECKS PASSED")
